sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if (!transformBuilder) return;

        var listModel = transformBuilder

        // do not remove
        .transform();

        /************************************************************
         * Allow editing only for Comments field
         * Make all other fields read-only
         ************************************************************/

        // CHANGE THIS if your actual field name is different
        var editableField = 'comments'; 
        // Example: var editableField = 'u_comments';

        // Make only Comments column editable
        if (listModel.columnDefinitions && listModel.columnDefinitions.columns) {
            listModel.columnDefinitions.columns.forEach(function(column) {

                if (column.key === editableField) {
                    column.editable = true;
                    column.readOnly = false;
                    column.disabled = false;
                } else {
                    column.editable = false;
                    column.readOnly = true;
                    column.disabled = true;
                }

            });
        }

        // Make only Comments cells editable in every row
        if (listModel.rowDefinitions && listModel.rowDefinitions.rows) {
            listModel.rowDefinitions.rows.forEach(function(row) {

                if (!row.cells) return;

                Object.keys(row.cells).forEach(function(cellKey) {
                    var cell = row.cells[cellKey];

                    if (cellKey === editableField) {
                        cell.editable = true;
                        cell.readOnly = false;
                        cell.disabled = false;
                    } else {
                        cell.editable = false;
                        cell.readOnly = true;
                        cell.disabled = true;
                    }
                });

            });
        }

        return listModel;
    }

    // do not remove
    catch (error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
